package com.lebzlon.measurementtracker.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserDetailsService uds; public JwtAuthFilter(JwtService j, UserDetailsService u){this.jwt=j; this.uds=u;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException, IOException { String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){ String t=h.substring(7); try{ var ud=uds.loadUserByUsername(jwt.extractUsername(t)); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(ud,null,ud.getAuthorities())); }catch(Exception ignored){} } chain.doFilter(req,res);} }
